CREATE FUNCTION public.origem_check_attempt(p_ip_hash text, p_success boolean) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE n integer; BEGIN PERFORM pg_advisory_xact_lock(hashtext(p_ip_hash)); SELECT count(*) INTO n FROM public.origem_attempts WHERE ip_hash=p_ip_hash AND NOT succeeded AND created_at > now()-interval '15 minutes'; IF n >= 8 THEN RETURN false; END IF; INSERT INTO public.origem_attempts(ip_hash,succeeded) VALUES(p_ip_hash,p_success); RETURN true; END $$;
REVOKE ALL ON FUNCTION public.origem_check_attempt(text,boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.origem_check_attempt(text,boolean) TO service_role;
CREATE FUNCTION public.origem_save(p_token_hash text,p_version bigint,p_payload jsonb) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_company uuid; v_version bigint; BEGIN SELECT c.id INTO v_company FROM public.origem_sessions s JOIN public.origem_companies c ON c.id=s.company_id WHERE s.token_hash=p_token_hash AND s.revoked_at IS NULL AND s.expires_at>now() AND c.blocked=false AND c.expires_at>now() FOR UPDATE OF s,c; IF v_company IS NULL THEN RAISE EXCEPTION 'ACCESS_DENIED'; END IF; UPDATE public.origem_data SET payload=p_payload,version=version+1 WHERE company_id=v_company AND version=p_version RETURNING version INTO v_version; IF v_version IS NULL THEN RAISE EXCEPTION 'VERSION_CONFLICT'; END IF; RETURN v_version; END $$;
REVOKE ALL ON FUNCTION public.origem_save(text,bigint,jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.origem_save(text,bigint,jsonb) TO service_role;